        border: none; border-radius: 12px; cursor: pointer;
        font-size: 0.93rem; font-weight: 700; color: #fff;
        background: linear-gradient(135deg, #4e54c8, #8f94fb);
        box-shadow: 0 6px 20px rgba(78,84,200,0.32);
