    @keyframes mmFadeIn { from{opacity:0;transform:translateY(4px)} to{opacity:1;transform:translateY(0)} }
    .mm-status-msg.info    { background:#eff6ff; color:#1d4ed8; border-color:#bfdbfe; }
    .mm-status-msg.success { background:#f0fdf4; color:#15803d; border-color:#bbf7d0; }
