    <script type="text/javascript">
        "use strict";
        // $('select').selectpicker();

        var item = $('.cart-item').length;
        $('#item').val(item);

        function copy_input(x, y) {
            $(y).val($(x).val());
        }

        if ($('#qr_code').is(':checked')) {
            $('#qr_code_section').show();
        } else {
            $('#qr_code_section').hide();
        }

        $('input[name="payment_mode"]').on('change', function() {
            // Show or hide QR code section
            if ($('#qr_code').is(':checked')) {
                $('#qr_code_section').show();
            } else {
                $('#qr_code_section').hide();
            }

            // Show or hide WhatsApp Order Note section
            if ($('#whatsapp_order_radio').is(':checked')) {
                $('#order_note_section').slideDown();
            } else {
                $('#order_note_section').slideUp();
                $('#order_note').val('');
            }
        });

        $("#register_guest").on('click', function(){
            if($("#register_guest").prop('checked') == true){
                $(this).val(1);
                $('.guest_password').css('display','block');
            }else{
                $(this).val(0);
                $('.guest_password').css('display','none');
            }
        })

        $('#name').on('input', function() {
            copy_input('#name', '#billing_name');
        });

        $('#phone').on('input', function() {
            copy_input('#phone', '#billing_phone');
        });

        $('#email').on('input', function() {
            copy_input('#email', '#billing_email');
        });

        $('#address').on('input', function() {
            copy_input('#address', '#billing_address');
        });

        $('#state').on('input', function() {
            copy_input('#state', '#billing_state');
        });

        $('#city').on('input', function() {
            copy_input('#city', '#billing_city');
        });

        $('#zip').on('input', function() {
            copy_input('#zip', '#billing_zip');
        });

        $('#country').on('changed.bs.select', function() {
            copy_input('#country', '#billing_country');
            // $('#billing_country').selectpicker('refresh');
        });

        if ($('#address_list').val() == '0') {
            $('.shipping_details input,.shipping_details select,.billing_details input,.billing_details select').val('');
            $('.shipping_details').removeClass('d-none');
            $('.default_address').addClass('d-none');
        }

        $('#address_list').on('change', function() {
            var def_address = $('input[name="default_address"]').val();
            if ((def_address.length > 0) && ($(this).val() == def_address)) {
                $('.default_address').removeClass('d-none');

                $('#name').val('{{$def_address->name ?? $customer->name ?? "" }}');
                copy_input('#name', '#billing_name');

                $('#phone').val('{{$def_address->phone ?? $customer->phone ?? ""}}');
                copy_input('#phone', '#billing_phone');

                $('#email').val('{{$def_address->email ?? $customer->email ?? ""}}');
                copy_input('#email', '#billing_email');

                $('#address').val('{{$def_address->address ?? ""}}');
                copy_input('#address', '#billing_address');

                $('#state').val('{{$def_address->state ?? ""}}');
                copy_input('#state', '#billing_state');

                $('#city').val('{{$def_address->city ?? ""}}');
                copy_input('#city', '#billing_city');

                $('#zip').val('{{$def_address->zip ?? ""}}');
                copy_input('#zip', '#billing_zip');

                $('#country').val('{{$def_address->country ?? ""}}');
                copy_input('#country', '#billing_country');
                // $('#country,#billing_country').selectpicker('refresh');

            } else if ($(this).val() == '0') {
                $('.shipping_details input,.shipping_details select,.billing_details input,.billing_details select').val('');
                $('.shipping_details').removeClass('d-none');
                $('.default_address').addClass('d-none');
            } else {
                $('.default_address').addClass('d-none');

                var url = '{{url("/customer/address/edit/")}}/' + $(this).val();
                $.ajax({
                    url: url,
                    type: "GET",
                    dataType: 'json',
                    success: function(data) {
                        if ((data.name) && data.name.length > 1) {
                            $('#name').val(data.name);
                            copy_input('#name', '#billing_name');
                        } else {
                            $('#name').val('{{$customer->name ?? "" }}');
                            copy_input('#name', '#billing_name');
                        }

                        if ((data.phone) && data.phone.length > 1) {
                            $('#phone').val(data.phone);
                            copy_input('#phone', '#billing_phone');
                        } else {
                            $('#phone').val('{{$customer->phone ?? "" }}');
                            copy_input('#phone', '#billing_phone');
                        }

                        if ((data.email) && data.phone.email > 1) {
                            $('#email').val(data.email);
                            copy_input('#email', '#billing_email');
                        } else {
                            $('#email').val('{{$customer->email ?? "" }}');
                            copy_input('#email', '#billing_email');
                        }

                        $('#address').val(data.address);
                        copy_input('#address', '#billing_address');
                        $('#city').val(data.city);
                        copy_input('#city', '#billing_city');
                        $('#state').val(data.state);
                        copy_input('#state', '#billing_state');
                        $('#zip').val(data.zip);
                        copy_input('#zip', '#billing_zip');
                        $('#country').val(data.country);
                        copy_input('#country', '#billing_country');
                        // $('#country,#billing_country').selectpicker('refresh');

                        $('.shipping_details').removeClass('d-none');
                    }
                })

            }
        })


        $('#payment-form').on('submit', function(e) {
            if ($('#whatsapp_order_radio').is(':checked')) {
                e.preventDefault();
                processWhatsAppOrder();
                return false;
            }

            var paymentMode = $('input[name="payment_mode"]:checked').val() || '';
            if (paymentMode === 'Mpesa' || paymentMode === 'MtnMoMo' || paymentMode === 'PayHere') {
                e.preventDefault();
                initiateMobileMoneyPayment(paymentMode);
                return false;
            }

            $('#go').attr("disabled", 'disabled').html('processing...');
        });

        var mmGateway = '';
        var mmCheckoutId = '';
        var mmPollInterval = null;
        var payherePayload = null;

        payhere.onCompleted = function onCompleted(orderId) {
            $('#mm-qr-status').removeClass('text-info text-danger').addClass('text-success').text('Payment Successful! Processing Order...');
            if (mmPollInterval) clearInterval(mmPollInterval);
            $('<input>').attr({type: 'hidden', name: 'payment_mode', value: mmGateway + '_Paid'}).appendTo('#payment-form');
            $('input[name="payment_mode"][type="radio"]').remove();
            $('#payment-form').off('submit').submit();
        };

        payhere.onDismissed = function onDismissed() {
            $('#mm-qr-status').removeClass('text-info text-success').addClass('text-danger').text('Payment dialog closed. Please try again.');
        };

        payhere.onError = function onError(error) {
            $('#mm-qr-status').removeClass('text-info text-success').addClass('text-danger').text('Payment error: ' + error);
        };

        function initiateMobileMoneyPayment(gateway) {
            mmGateway = gateway;

            // Apply theme
            var $header  = $('#mm-modal-header');
            var $amtBar  = $('#mm-amount-bar');
            var $badge   = $('#mm-brand-badge');
            var $sendBtn = $('#btn-send-push');
            var $steps   = $('.mm-step');
            var $wrap    = $('#mm-phone-wrap');
            var $corners = $('#mm-qr-outer .mm-corner-tl, #mm-qr-outer .mm-corner-tr, #mm-qr-outer .mm-corner-bl, #mm-qr-outer .mm-corner-br');

            // Reset themes
            $header.removeClass('momo-theme payhere-theme');
            $amtBar.removeClass('momo-theme payhere-theme');
            $('#mm-spin').removeClass('momo-spin');
            $sendBtn.removeClass('momo-btn');
            $wrap.removeClass('momo-input');
            $steps.removeClass('momo-active');

            if (gateway === 'Mpesa') {
                $badge.html('M&#8209;PESA').removeClass('momo-badge');
                $('#mm-title').text('Pay with M-Pesa');
                $('#mm-step-1').addClass('mm-active');
                $('#mm-phone-hint').html('Include country code &mdash; <strong>254</strong> Kenya &bull; <strong>256</strong> Uganda');
            } else if (gateway === 'MtnMoMo') {
                $header.addClass('momo-theme');
                $amtBar.addClass('momo-theme');
                $badge.html('MTN<br>MoMo').addClass('momo-badge');
                $('#mm-title').text('Pay with MTN MoMo');
                $('#mm-spin').addClass('momo-spin');
                $sendBtn.addClass('momo-btn');
                $wrap.addClass('momo-input');
                $('#mm-step-1').addClass('momo-active');
                $('#mm-phone-hint').html('Include country code &mdash; <strong>256</strong> Uganda &bull; <strong>237</strong> Cameroon');
            } else if (gateway === 'PayHere') {
                $header.addClass('payhere-theme');
                $amtBar.addClass('payhere-theme');
                $badge.html('Pay<br>Here').removeClass('momo-badge');
                $('#mm-title').text('Pay with PayHere');
            }

            // Show amount
            var amt = Number(checkoutQuote.display.grand_total || 0).toFixed(2);
            $('#mm-display-amount').text(amt);

            $('#mobile-money-modal').modal('show');
            $('#mm-push-status').hide().text('');
            $('#mm-qr-status').hide().text('');
            $('#btn-send-push').attr('disabled', false);
            payherePayload = null;

            // Reset step indicators
            $('.mm-step').removeClass('mm-active mm-done momo-active');
            if (gateway === 'MtnMoMo') {
                $('#mm-step-1').addClass('momo-active');
            } else {
                $('#mm-step-1').addClass('mm-active');
            }

            // Reset QR box state
            $('#mm-qr-container').removeClass('qr-loaded momo-qr')
                .html('<div class="mm-qr-loading"><div class="mm-spinner' + (gateway === 'MtnMoMo' ? ' momo-spin' : '') + '" id="mm-spin"></div><span>Generating QR Code...</span></div>');

            if (gateway === 'PayHere') {
                $('#mm-push-section').hide();
                $('#mm-or-divider').hide();
                $('#mm-payhere-section').show();
            } else {
                $('#mm-push-section').show();
                $('#mm-or-divider').show();
                $('#mm-payhere-section').hide();
                var phone = $('input[name="shipping_phone"]').val() || $('input[name="billing_phone"]').val() || '';
                $('#mm_phone').val(phone);
            }

            generateMobileMoneyQr(gateway);
        }

        function generateMobileMoneyQr(gateway) {
            var isMomo = (gateway === 'MtnMoMo');
            $('#mm-qr-container').removeClass('qr-loaded momo-qr')
                .html('<div class="mm-qr-loading"><div class="mm-spinner' + (isMomo ? ' momo-spin' : '') + '"></div><span>Generating QR Code...</span></div>');

            var amount = checkoutQuote.display.grand_total;
            var order_id = 'ecomm-' + Date.now();

            var url = '';
            if (gateway === 'Mpesa')   url = '{{ url("ecommerce/mpesa/qr") }}';
            else if (isMomo)           url = '{{ url("ecommerce/momo/qr") }}';
            else if (gateway === 'PayHere') url = '{{ url("ecommerce/payhere/push") }}';

            $.post(url, { _token: '{{ csrf_token() }}', amount: amount, order_id: order_id })
                .done(function(res) {
                    if (res.success || res.qr_checkout_url) {
                        if (gateway === 'PayHere') {
                            mmCheckoutId = res.order_id || order_id;
                            payherePayload = res.payload;
                            if (res.sandbox) payherePayload.sandbox = true;
                            var qrData = res.qr_checkout_url || res.qr_code;
                            var qrImageUrl = 'https://api.qrserver.com/v1/create-qr-code/?size=180x180&data=' + encodeURIComponent(qrData);
                            $('#mm-qr-container').html('<img src="' + qrImageUrl + '" alt="QR Code">').addClass('qr-loaded');
                            $('#mm-qr-status').show().removeClass('danger success').addClass('info').text('Scan QR or click Pay Online Now below...');
                            $('#btn-payhere-link').off('click').on('click', function(e) {
                                e.preventDefault();
                                if (payherePayload) payhere.startPayment(payherePayload);
                            });
                            startPolling();
                        } else {
                            $('#mm-qr-container')
                                .html('<img src="data:image/png;base64,' + res.qr_code + '" alt="QR Code">')
                                .addClass('qr-loaded' + (isMomo ? ' momo-qr' : ''));
                            if (isMomo) $('#mm-qr-outer').addClass('mm-corners-momo');
                            $('#mm-qr-status').show().removeClass('danger success').addClass('info')
                                .text('Waiting for payment confirmation...');
                        }
                    } else {
                        $('#mm-qr-container').html('<p style="color:#dc2626;font-size:0.8rem;padding:8px;">' + (res.message || 'Failed to generate QR') + '</p>');
                    }
                }).fail(function() {
                    $('#mm-qr-container').html('<p style="color:#dc2626;font-size:0.8rem;padding:8px;">Failed to generate QR. Check credentials.</p>');
                });
        }

        $('#btn-send-push').on('click', function() {
            var phone = $('#mm_phone').val().trim();
            if (!phone) {
                $('#mm-push-status').show().attr('class', 'mm-status-msg danger').text('Please enter a phone number.');
                return;
            }
            $(this).attr('disabled', true);
            var $status = $('#mm-push-status');
            $status.show().attr('class', 'mm-status-msg info').text('Sending request to your phone...');

            // Advance step
            $('#mm-step-1').addClass('mm-done').removeClass('mm-active momo-active');
            var isMomo = (mmGateway === 'MtnMoMo');
            if (isMomo) $('#mm-step-2').addClass('momo-active'); else $('#mm-step-2').addClass('mm-active');

            var amount = checkoutQuote.display.grand_total;
            var url = isMomo ? '{{ url("ecommerce/momo/push") }}' : '{{ url("ecommerce/mpesa/push") }}';

            $.post(url, { _token: '{{ csrf_token() }}', phone: phone, amount: amount })
                .done(function(res) {
                    if (res.success) {
                        $status.attr('class', 'mm-status-msg info').text(res.message || 'STK Push sent! Check your phone.');
                        mmCheckoutId = res.CheckoutRequestID || res.reference_id || '';
                        if (mmCheckoutId) startPolling();
                    } else {
                        $('#btn-send-push').attr('disabled', false);
                        $('#mm-step-2').removeClass('mm-active momo-active');
                        $status.attr('class', 'mm-status-msg danger').text(res.message || 'Request failed.');
                    }
                }).fail(function(xhr) {
                    $('#btn-send-push').attr('disabled', false);
                    $('#mm-step-2').removeClass('mm-active momo-active');
                    var msg = xhr.responseJSON && xhr.responseJSON.message ? xhr.responseJSON.message : 'Request failed. Try again.';
                    $status.attr('class', 'mm-status-msg danger').text(msg);
                });
        });

        function startPolling() {
            if (mmPollInterval) clearInterval(mmPollInterval);
            var url = '';
            if (mmGateway === 'Mpesa')   url = '{{ url("ecommerce/mpesa/status") }}';
            else if (mmGateway === 'MtnMoMo') url = '{{ url("ecommerce/momo/status") }}';
            else if (mmGateway === 'PayHere') url = '{{ url("ecommerce/payhere/status") }}';

            mmPollInterval = setInterval(function() {
                $.post(url, { _token: '{{ csrf_token() }}', checkout_request_id: mmCheckoutId, reference_id: mmCheckoutId })
                    .done(function(res) {
                        if (res.status === 'success') {
                            clearInterval(mmPollInterval);
                            // Mark all steps done
                            $('.mm-step').removeClass('mm-active momo-active').addClass('mm-done');
                            var $msg = '<span style="font-size:1.1rem;">&#10003;</span> Payment Successful! Processing your order...';
                            $('#mm-push-status').show().attr('class', 'mm-status-msg success').html($msg);
                            $('#mm-qr-status').show().attr('class', 'mm-status-msg success').html($msg);
                            $('<input>').attr({type: 'hidden', name: 'payment_mode', value: mmGateway + '_Paid'}).appendTo('#payment-form');
                            $('input[name="payment_mode"][type="radio"]').remove();
                            setTimeout(function() { $('#payment-form').off('submit').submit(); }, 800);
                        } else if (res.status === 'failed' || res.status === 'cancelled') {
                            clearInterval(mmPollInterval);
                            var errMsg = 'Payment ' + res.status + '. ' + (res.message || 'Please try again.');
                            $('#mm-push-status').show().attr('class', 'mm-status-msg danger').text(errMsg);
                            $('#mm-qr-status').show().attr('class', 'mm-status-msg danger').text(errMsg);
                            $('#mm-step-2, #mm-step-3').removeClass('mm-active momo-active mm-done');
                            $('#btn-send-push').attr('disabled', false);
                        }
                    });
            }, 5000);
        }

        $('#mobile-money-modal').on('hidden.bs.modal', function () {
            if (mmPollInterval) clearInterval(mmPollInterval);
        });

        var checkoutQuote = @json($quote);

        function renderCheckoutQuote(quote) {
            checkoutQuote = quote;
            $('.sub_total').text(Number(quote.display.sub_total).toFixed({{$general_setting->decimal}}));
            $('#coupon_discount_display').text(Number(quote.display.coupon_discount).toFixed({{$general_setting->decimal}}));
            $('#tax_total').text(Number(quote.display.total_tax).toFixed({{$general_setting->decimal}}));
            $('#shipping_cost').text(Number(quote.display.shipping_cost).toFixed({{$general_setting->decimal}}));
            $('#total').text(Number(quote.display.grand_total).toFixed({{$general_setting->decimal}}));
        }

        function refreshCheckoutQuote() {
            return $.ajax({
                url: "{{ route('checkout.quote') }}",
                type: "POST",
                data: {
                    coupon_code: $('#coupon_code').val() || null,
                    delivery_area_id: $('#delivery_area_id').val() || null
                },
                success: renderCheckoutQuote,
                error: function(xhr) {
                    var message = xhr.responseJSON && xhr.responseJSON.message
                        ? xhr.responseJSON.message
                        : @json(__('db.Ecommerce checkout unavailable'));
                    $('.alert').addClass('alert-danger show');
                    $('.alert-danger .message').html(message);
                }
            });
        }

        $(document).on('click', '.apply-coupon', function(e) {
            e.preventDefault();
            if ($('#coupon_code').val() === '') {
                $('.alert').addClass('alert-danger show');
                $('.alert-danger .message').html('Please enter a valid coupon code');
            } else {
                $('.apply-coupon').attr('disabled', true);
                refreshCheckoutQuote().always(function() {
                    $('.apply-coupon').attr('disabled', false);
                });
            }
        });

        $("#different_billing").change(function() {
            if ($(this).is(':checked')) {
                $('#billingAddress').removeClass('show');
            } else {
                $('#billingAddress').addClass('show');
            }
        });

        $(document).on('click', '.pay-button', function(e) {
            $('.pay-button').removeClass('selected');
            $(this).toggleClass('selected');
        });


       /* whatsapp order */
    // 🔥 Helper: Clean + Add 88
    function formatPhoneNumber(number) {
        number = (number || '').toString().replace(/\D/g, '');

        if (!number) return '';

        return number;
    }

    function processWhatsAppOrder() {
        var name    = $('#name').val()?.trim() || '';
        var phone   = $('#phone').val()?.trim() || '';
        var email   = $('#email').val()?.trim() || '';
        var address = $('#address').val()?.trim() || '';
        var city    = $('#city').val()?.trim() || '';

        if (!name || !email || !address || !city) {
            $('.alert').addClass('alert-custom show');
            $('.alert-custom .message').html('Please fill in the required fields first.');
            setTimeout(function() { $('.alert').removeClass('show'); }, 4000);
            return;
        }

        var rawStorePhone = '{{ $ecommerce_setting->store_phone ?? "" }}';
        var storePhone = formatPhoneNumber(rawStorePhone);

        if (!storePhone) {
            SaleProToast.warning('WhatsApp number is not configured.');
            return;
        }

        $('#go').attr("disabled", 'disabled').html('processing...');

        var currencySymbol = '{{ $currency->symbol ?? $currency->code }}';
        var divider     = '━━━━━━━━━━━━━━━━━━━━━━';
        var thinDivider = '┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄┄';

        // ── Header ──
        var message = '';
        message += '*NEW ORDER RECEIVED*\n';
        message += divider + '\n\n';

        // ── Customer Info ──
        message += '*CUSTOMER DETAILS*\n';
        message += thinDivider + '\n';
        message += 'Name    : ' + name             + '\n';
        message += 'Phone   : ' + (phone || '—')   + '\n';
        message += 'Email   : ' + email             + '\n';
        message += 'Address : ' + address + ', ' + city + '\n';
        message += divider + '\n\n';

        // ── Order Items ──
        message += '*ORDER ITEMS*\n';
        message += thinDivider + '\n';

        var itemIndex = 1;
        $('.cart-item').each(function() {
            var itemName = $(this).find('.fw-500').first().text().trim();

            var qtyEl   = $(this).find('.item-qty').text().trim();
            var priceEl = $(this).find('.item-price').text().trim();

            // fallback
            if (!qtyEl && !priceEl) {
                var spans = $(this).find('span');
                qtyEl   = spans.eq(0).text().trim();
                priceEl = spans.eq(1).text().trim();
            }

            message += itemIndex + '. *' + itemName + '*\n';
            message += '    Qty   : ' + qtyEl   + '\n';
            message += '    Price : ' + priceEl + '\n';
            message += thinDivider + '\n';
            itemIndex++;
        });

        // ── Pricing Summary ──
        var subTotal = parseFloat($('.sub_total').text() || 0).toFixed(2);
        var shipping = $('#shipping_cost').text().trim() || '0.00';
        var total    = $('#total').text().trim()         || '0.00';

        message += '\n*PRICE SUMMARY*\n';
        message += thinDivider + '\n';
        message += 'Sub Total  : ' + currencySymbol + ' ' + subTotal + '\n';
        message += 'Shipping   : ' + currencySymbol + ' ' + shipping + '\n';
        message += divider + '\n';
        message += '*Grand Total: ' + currencySymbol + ' ' + total + '*\n';
        message += divider + '\n\n';

        // ── Payment ──
        var paymentMode = $('input[name="payment_mode"]:checked').val() || 'Cash on Delivery';
        message += '*Payment Mode:* ' + paymentMode + '\n';

        // ── Note ──
        var note = $('#sale_note').val()?.trim();
        var moreInfo = $('#order_note').val()?.trim();
        if (note) {
            message += '*Note:* ' + note + '\n';
        }
        if (moreInfo) {
            message += '*More Payment Info:* ' + moreInfo + '\n';
        }

        message += '\n' + divider;

        // ── Place Order & Open WhatsApp ──
        $.ajax({
            url: "{{ url('/place-order') }}",
            type: "POST",
            data: $('#payment-form').serialize() + '&payment_mode=whatsapp_order',
            success: function(response) {
                var reference = response.reference || 'N/A';
                message += '\n*Order Ref:* #' + reference;
                message += '\n' + divider;
                window.open('https://wa.me/' + storePhone + '?text=' + encodeURIComponent(message), '_blank');
                // Redirect to thank you page or success
                location.href = "{{url('order/success')}}/" + reference;
            },
            error: function() {
                $('#go').removeAttr("disabled").html("{{__('db.Place Order')}}");
                SaleProToast.error('Something went wrong. Please try again.');
            }
        });
    }

    function openWhatsApp(phone, message) {
        window.open('https://wa.me/' + phone + '?text=' + encodeURIComponent(message), '_blank');
    }

    $('#delivery_area_id').on('change', function () {
        refreshCheckoutQuote();
    });
    </script>

</body>

</html>
